from selenium.common.exceptions import StaleElementReferenceException, WebDriverException

from taf.rfrl.procedures.resources.python.logger import log_input_and_output
from taf.rfrl.procedures.resources.python.decorators import repeat_operation_when_exception_occurs
from taf.rfrl.procedures.resources.python.webui.engine_factory import EngineFactory


class webui(object):

    def __init__(self):
        self._engine = None

    def __str__(self):
        return self._engine.__str__()

    @log_input_and_output
    def configure(self, sw_stream):
        """
        Configures webui instance according to given sw_stream
        :param sw_stream: software stream i.e. '5G20B'
        :type sw_stream: str
        """
        self._engine = EngineFactory.create_engine(sw_stream)
        return self

    @log_input_and_output
    def lock_cell(self, cell_id=1, timeout=60):
        """
        Locks cell
        :param cell_id: index of cell to be locked
        :type cell_id: int
        :param timeout: timeout
        :type timeout: int
        """
        self._engine.lock_cell(cell_id=int(cell_id), timeout=int(timeout))

    @log_input_and_output
    def block_cell(self, cell_id=1, timeout=60):
        """
        Blocks cell
        :param cell_id: index of cell to be blocked
        :type cell_id: int
        :param timeout: timeout
        :type timeout: int
        """
        self._engine.block_cell(cell_id=int(cell_id), timeout=int(timeout))

    @repeat_operation_when_exception_occurs(exception=WebDriverException, rep_number=2, sleep_time=5)
    @log_input_and_output
    def login(self, url, username, password, screenshot_dir=None, download_dir=None, browser='Firefox',
              sync_full_rack=False):
        """
        Logs in and disables message box
        :param url: url
        :type url: str
        :param username: username to log in
        :type username: str
        :param password: password to log in
        :type password: str
        :param screenshot_dir: directory where the screenshots will be saved
        :type screenshot_dir: str
        :param download_dir: directory for downloading files
        :type download_dir: str
        :param browser: WebDriver instance or "Chrome" or "Firefox" or alias name for self-created webdriver, Firefox
        is used as default
        :type browser: Optional[WebDriver, str]
        :param sync_full_rack: states if full rack synchronization should be performed
        :type sync_full_rack: bool
        """
        self._engine.login(url, username, password, screenshot_dir, download_dir, browser, sync_full_rack)

