    @log_input_and_output
    def get_detailed_result_for_each_antenna(self, cell_id, timeout=60):
        """
        Gets detailed result for each antenna table from RF Diagnostic Test Results page.

        Returned value will be as below:
            [{'Antenna/Port': 'ANT1',
              'Forward expected transmit RF power': {'W': '0', 'dBm': '0'},
              'Forward total transmit RF power': {'W': '0', 'dBm': '7'},
              'Forward transmit RF power error (dB)': '0',
              'RSSI (dBm)': '0',
              'RTWP (dBm)': '0',
              'Radio module': 'RMOD-1(AWHHD)',
              'VSWR': '0'},
             {'Antenna/Port': 'ANT3',
              'Forward expected transmit RF power': {'W': '0', 'dBm': '0'},
              'Forward total transmit RF power': {'W': '0', 'dBm': '0'},
              'Forward transmit RF power error (dB)': '0',
              'RSSI (dBm)': '-140',
              'RTWP (dBm)': '-101.1',
              'Radio module': 'RMOD-1(AWHHD)',
              'VSWR': '0'}
            ]

        :param cell_id: cell id to filter, if not passed, default is None, then will get default table value on webem.
                        If passed value, will filter by cell filter on webem:
                        1) CellIdNotFound will be raised if wrong cell id passed.
                        2) if correct cell id found, then returns general test information for this cell.
        :type cell_id: str
        :param timeout: timeout
        :type timeout: int
        :return: list of detailed result for each antenna table
        :rtype: list
        """
        return self._engine.get_detailed_result_for_each_antenna(cell_id=cell_id, timeout=int(timeout))

