    @log_input_and_output
    def set_parameter_value(self, dist_name, filter_param, new_value=None, node_index=None,
                            parameter_status="All parameters", abbr=None, bts_configuration='Current', timeout=60):
        """
        Sets parameter value
        :param dist_name:  dist name for parameters to filter, cannot be none
        :type dist_name: str
        :param filter_param: param to locate target parameter, cannot be none
        :type filter_param: str
        :param new_value: when new_value is None, parameter will use its default value
        :type new_value: str, none, int or list
        :param node_index: param to filter child node if other params can not locate only one
        :type node_index: int or none
        :param parameter_status: param to select parameter status, "All parameters", "Mandatory parameters",
        "Optional parameters" can be passed on
        :type parameter_status: str
        :param abbr: abbreviation to further locate target parameter
        :type abbr: str or none
        :param bts_configuration: "Current" or "Planned" bts configuration can be used
        :type bts_configuration: str
        :param timeout: timeout
        :type timeout: int
        """
        node_index = int(node_index) if node_index is not None else node_index
        self._engine.set_parameter_value(dist_name=dist_name, filter_param=filter_param, new_value=new_value,
                                         node_index=node_index, parameter_status=parameter_status, abbr=abbr,
                                         bts_configuration=bts_configuration, timeout=int(timeout))

