    def get_general_test_information(self, cell_id=None, timeout=60):
        """
        Gets general test information table from RF Diagnostic Test Results page.

        Returned value will be as below:
            [{'Forward test disposition': 'Fail',
              'Outcome': 'Failed',
              'Reverse test disposition': 'Fail',
              'Start time GMT +0800': '01.04.2021 18:04:21',
              'Stop time GMT +0800': '01.04.2021 18:04:22'},
            {'Forward test disposition': 'Fail',
             'Outcome': 'Failed',
             'Reverse test disposition': 'Fail',
             'Start time GMT +0800': '01.04.2021 15:35:39',
             'Stop time GMT +0800': '01.04.2021 15:35:40'}]

        :param cell_id: cell id to filter, if not passed, default is None, then will get default table value on webem.
                        If passed value, will filter by cell filter on webem:
                        1) CellIdNotFound will be raised if wrong cell id passed.
                        2) if correct cell id found, then returns general test information for this cell.
        :type cell_id: str
        :param timeout: timeout
        :type timeout: int
        :return: list of test information table
        :rtype: list of dict
        """
        return self._engine.get_general_test_information(cell_id=cell_id, timeout=int(timeout))
